// leanBench static site — list + detail views + charts.
//
// Data contract: `results/index.json` lists all runs grouped by machine;
// per-run detail comes from `results/<filename>.json`. The index is
// regenerated by scripts/build_index.py at deploy time (not committed).

const page = document.body.dataset.page
  || (location.pathname.endsWith("/result.html") ? "result"
      : location.pathname.endsWith("/run.html") ? "run"
      : "index");


const fmtNs = (ns) => {
  if (ns == null || Number.isNaN(ns)) return "—";
  if (ns < 10_000) return `${ns} ns`;
  if (ns < 10_000_000) return `${(ns / 1e3).toFixed(1)} µs`;
  if (ns < 10_000_000_000) return `${(ns / 1e6).toFixed(2)} ms`;
  return `${(ns / 1e9).toFixed(2)} s`;
};

const fmtBytes = (b) => {
  if (b == null) return "—";
  if (b < 1024) return `${b} B`;
  if (b < 1024 * 1024) return `${(b / 1024).toFixed(1)} KiB`;
  if (b < 1024 ** 3) return `${(b / 1024 ** 2).toFixed(1)} MiB`;
  return `${(b / 1024 ** 3).toFixed(2)} GiB`;
};

const fmtDate = (iso) => {
  if (!iso) return "—";
  try {
    const d = new Date(iso);
    return d.toISOString().replace("T", " ").slice(0, 16) + " UTC";
  } catch { return iso; }
};

// Compact, glanceable relative time for the "last updated" stat — avoids
// wrapping 20+ characters of ISO timestamp into the big stat cell.
const fmtRelative = (iso) => {
  if (!iso) return "—";
  try {
    const d = new Date(iso);
    const diffS = (d.getTime() - Date.now()) / 1000;
    const abs = Math.abs(diffS);
    const rtf = new Intl.RelativeTimeFormat("en", { numeric: "auto" });
    if (abs < 60) return rtf.format(Math.round(diffS), "second");
    if (abs < 3600) return rtf.format(Math.round(diffS / 60), "minute");
    if (abs < 86400) return rtf.format(Math.round(diffS / 3600), "hour");
    if (abs < 86400 * 30) return rtf.format(Math.round(diffS / 86400), "day");
    return d.toISOString().slice(0, 10);
  } catch { return iso; }
};

const el = (tag, attrs = {}, ...children) => {
  const n = document.createElement(tag);
  for (const [k, v] of Object.entries(attrs)) {
    if (k === "class") n.className = v;
    else if (k === "text") n.textContent = v;
    else if (k.startsWith("on")) n.addEventListener(k.slice(2), v);
    else n.setAttribute(k, v);
  }
  for (const c of children) {
    if (c == null) continue;
    n.appendChild(typeof c === "string" ? document.createTextNode(c) : c);
  }
  return n;
};

// Round `v` up to the next "nice" axis tick: 1/1.5/2/2.5/3/4/5/7.5/10
// times the appropriate power of ten. Used to give comparison charts a
// readable upper bound on the x-axis instead of `maxValue * 1.04`.
const niceCeil = (v) => {
  if (!(v > 0)) return 1;
  const exp = Math.pow(10, Math.floor(Math.log10(v)));
  const f = v / exp;
  const fractions = [1, 1.5, 2, 2.5, 3, 4, 5, 7.5, 10];
  return fractions.find((nf) => nf >= f) * exp;
};

// Colour palette for series — keeps machine lines visually distinct.
const PALETTE = [
  "#4a46d9", "#0891b2", "#16a34a", "#d97706",
  "#be185d", "#7c3aed", "#0369a1", "#ea580c",
];
const colorFor = (i) => PALETTE[i % PALETTE.length];

// Display toggle: log vs linear y-axis on the sweep / combined charts. Default
// linear; flipped by the "log scale" checkbox on the run and trend pages, which
// then re-render. Log can't begin at zero, so callers gate beginAtZero on it.
// Persisted in localStorage (shared key) so the choice sticks across reloads
// and stays consistent between the run and trend pages.
const LOG_SCALE_KEY = "leanbench.logScale";
let useLogScale = (() => {
  try { return localStorage.getItem(LOG_SCALE_KEY) === "1"; } catch { return false; }
})();
const yAxisType = () => (useLogScale ? "logarithmic" : "linear");

// Wire the "log scale" checkbox (if the page has one) to flip useLogScale,
// persist it, and re-render via the page's own rerender fn.
function wireLogToggle(rerender) {
  const toggle = document.querySelector("#log-scale-toggle");
  if (!toggle) return;
  toggle.checked = useLogScale;
  toggle.onchange = () => {
    useLogScale = toggle.checked;
    try { localStorage.setItem(LOG_SCALE_KEY, useLogScale ? "1" : "0"); } catch { /* private mode */ }
    rerender();
  };
}

// Machines hidden from every aggregate view. Their result files stay on disk;
// they're just not charted or listed. c4-standard-4 (4 vCPU / 2 physical) was
// dropped from the benchmark matrix, so we stop surfacing its historical runs.
const HIDDEN_MACHINE_LABELS = new Set(["c4-standard-4"]);
const visibleMachines = (machines) =>
  (machines || []).filter((m) => !HIDDEN_MACHINE_LABELS.has(m.label));

const chartTheme = () => {
  const dark = matchMedia("(prefers-color-scheme: dark)").matches;
  return {
    text: dark ? "#f0f0ea" : "#1a1a1a",
    grid: dark ? "#2a2a32" : "#e5e5e0",
  };
};

// Apply theme defaults to Chart.js globally.
(() => {
  if (typeof Chart === "undefined") return;
  const t = chartTheme();
  Chart.defaults.color = t.text;
  Chart.defaults.borderColor = t.grid;
  Chart.defaults.font.family = getComputedStyle(document.body)
    .getPropertyValue("--sans") || "-apple-system, sans-serif";
})();


// Site-wide config (e.g. default branch filter for all branch dropdowns).
// Fetched once from site/config.json on first need; falls back to an
// empty object if the file is missing or malformed.
let leanBenchConfig = null;
async function loadLeanBenchConfig() {
  if (leanBenchConfig) return leanBenchConfig;
  try {
    leanBenchConfig = await fetch("config.json").then((r) => r.json());
  } catch { leanBenchConfig = {}; }
  return leanBenchConfig;
}

// Active (leansig, leanmultisig) SHA pair. Runs from other combos are hidden
// from the stats row, compare charts, and machine cards. Defaults to the
// most-recent combo (sorted server-side).
let indexData = null;
let activeCombo = null;
// Branch filter — narrows the combo dropdown to combos on the chosen
// leanVM branch (`null` = any branch). leanVM is the main switcher;
// leanSig branch lives inside the combo dropdown options instead of its
// own filter. Combo selection (SHA pair) stays orthogonal.
let activeLeanvmBranch = null;

async function renderRun() {
  try {
    indexData = await fetch("results/index.json").then((r) => r.json());
    indexData.machines = visibleMachines(indexData.machines);
  } catch (e) {
    document.querySelector("#machines").innerHTML =
      `<p>No results yet. Run <code>uv run bench</code>, commit, push, and the
       site will populate.</p>`;
    return;
  }

  const combos = indexData.combos || [];
  const cfg = await loadLeanBenchConfig();
  // URL > config default > null. Validate against actual combo set so
  // a stale config doesn't strand the page on an empty filter.
  const available = new Set(combos.map((c) => c.leanmultisig_branch).filter(Boolean));
  const requested = leanvmBranchFromUrl() ?? cfg.default_leanvm_branch ?? null;
  activeLeanvmBranch = (requested && available.has(requested)) ? requested : null;
  const filtered = filterCombosByBranch(combos, activeLeanvmBranch);
  // Restore last-picked combo from URL (`?leansig=<sha>&leanmultisig=<sha>`)
  // so a refresh keeps the user's selection. Falls back to most-recent combo
  // when the URL has no params; *warns* (rather than silently falling back)
  // when the URL had params but no combo matches — silent fallback can mask a
  // stale link or a deleted combo. Branch filter is applied first so the
  // fallback respects the chosen branch scope.
  const pick = comboFromUrl(filtered);
  if (pick.requested && !pick.found) {
    showComboMissingWarning(pick.requested);
  }
  activeCombo = pick.found || filtered[0] || null;
  renderBranchFilter(combos);
  renderComboFilter(filtered);
  wireLogToggle(rerenderRunForCombo);
  rerenderRunForCombo();
}

function comboFromUrl(combos) {
  const params = new URLSearchParams(location.search);
  const ls = params.get("leansig");
  const lm = params.get("leanmultisig");
  if (!ls || !lm) return { requested: null, found: null };
  const found = combos.find((c) =>
    c.leansig_sha.startsWith(ls) && c.leanmultisig_sha.startsWith(lm)
  ) || null;
  return { requested: { leansig: ls, leanmultisig: lm }, found };
}

function leanvmBranchFromUrl() {
  return new URLSearchParams(location.search).get("leanmultisig_branch") || null;
}

function filterCombosByBranch(combos, branch) {
  return branch ? combos.filter((c) => c.leanmultisig_branch === branch) : combos;
}

function syncBranchToUrl() {
  const params = new URLSearchParams(location.search);
  if (activeLeanvmBranch) params.set("leanmultisig_branch", activeLeanvmBranch);
  else params.delete("leanmultisig_branch");
  const search = params.toString();
  const url = location.pathname + (search ? "?" + search : "") + location.hash;
  history.replaceState(null, "", url);
}

function showComboMissingWarning(requested) {
  const filter = document.querySelector("#filter");
  if (!filter || filter.querySelector(".combo-warning")) return;
  const warn = el("div", { class: "combo-warning" },
    `Requested commit (leanVM ${requested.leanmultisig} · leanSig ${requested.leansig}) `
    + `is not in the index — showing the most-recent commit instead. Pick another from the dropdown to update the URL.`,
  );
  filter.insertBefore(warn, filter.firstChild);
}

function syncComboToUrl(combo) {
  const params = new URLSearchParams(location.search);
  if (combo) {
    // Short prefix is enough — full SHAs in URLs are noisy. We match by
    // startsWith() above, so 8 chars is safely unique within a combo set.
    params.set("leansig", shortSha(combo.leansig_sha));
    params.set("leanmultisig", shortSha(combo.leanmultisig_sha));
  } else {
    params.delete("leansig");
    params.delete("leanmultisig");
  }
  const search = params.toString();
  const url = location.pathname + (search ? "?" + search : "") + location.hash;
  history.replaceState(null, "", url);
}

function sameCombo(a, b) {
  return a && b
    && a.leansig_sha === b.leansig_sha
    && a.leanmultisig_sha === b.leanmultisig_sha;
}

function runMatchesCombo(run, combo) {
  if (!combo) return true;
  const s = run.git_shas || {};
  return s.leansig_sha === combo.leansig_sha
      && s.leanmultisig_sha === combo.leanmultisig_sha;
}

function filteredMachines(machines, combo) {
  return machines
    .map((m) => ({ ...m, runs: (m.runs || []).filter((r) => runMatchesCombo(r, combo)) }))
    .filter((m) => m.runs.length > 0);
}

// Populate the leanVM branch <select> from the full combo list (so all
// branches stay reachable even when the current filter narrows the combo
// dropdown) and re-render the combo dropdown when it changes.
function renderBranchFilter(allCombos) {
  const select = document.querySelector("#branch-filter-leanvm");
  const branches = [...new Set(allCombos.map((c) => c.leanmultisig_branch).filter(Boolean))].sort();
  select.innerHTML = "";
  select.appendChild(new Option("all branches", ""));
  for (const v of branches) {
    select.appendChild(new Option(v, v, false, v === activeLeanvmBranch));
  }
  select.onchange = () => { activeLeanvmBranch = select.value || null; onBranchFilterChange(); };
}

function onBranchFilterChange() {
  syncBranchToUrl();
  const filtered = filterCombosByBranch(indexData.combos || [], activeLeanvmBranch);
  // Stay on the active combo if it still matches; otherwise jump to the
  // most-recent combo within the new filter scope. Silent — UX assumption
  // is that picking a branch is a deliberate "show me runs on this branch"
  // gesture, so quietly advancing the combo selection is the right behavior.
  if (!filtered.some((c) => sameCombo(c, activeCombo))) {
    activeCombo = filtered[0] || null;
    syncComboToUrl(activeCombo);
    document.querySelector(".combo-warning")?.remove();
  }
  renderComboFilter(filtered);
  rerenderRunForCombo();
}

function renderComboFilter(combos) {
  const details = document.querySelector("#combo-filter");
  const label   = details.querySelector(".combo-label");
  const menu    = document.querySelector("#combo-menu");

  // Click outside to close. Guarded so re-renders (e.g. after a branch
  // filter change) don't stack the listener.
  if (!details.dataset.outsideClickBound) {
    document.addEventListener("click", (e) => {
      if (details.open && !details.contains(e.target)) details.open = false;
    });
    details.dataset.outsideClickBound = "1";
  }

  if (!combos.length) {
    label.textContent = activeLeanvmBranch ? "no commits on this branch" : "no runs yet";
    details.open = false;
    details.style.pointerEvents = "none";
    menu.innerHTML = "";
    return;
  }
  details.style.pointerEvents = "";

  const updateLabel = () => {
    label.innerHTML = "";
    label.appendChild(comboLabelDom(activeCombo));
    details.title = comboFullLabel(activeCombo);
  };
  updateLabel();

  menu.innerHTML = "";
  for (const c of combos) {
    const active = sameCombo(c, activeCombo);
    const opt = el("div", { class: `combo-option${active ? " active" : ""}`,
      title: comboFullLabel(c).replace(" · ", "\n") },
      el("div", { class: "combo-option-shas" }, comboLabelDom(c, /*withTime=*/false)),
      el("div", { class: "combo-option-meta",
        text: `${fmtRelative(c.latest_run_ts)} · ${c.run_count} run${c.run_count === 1 ? "" : "s"}` }),
    );
    opt.addEventListener("click", () => {
      activeCombo = c;
      details.open = false;
      updateLabel();
      for (const o of menu.querySelectorAll(".combo-option")) o.classList.remove("active");
      opt.classList.add("active");
      syncComboToUrl(c);
      // Picking a valid combo resolves the "not found" condition.
      document.querySelector(".combo-warning")?.remove();
      rerenderRunForCombo();
    });
    menu.appendChild(opt);
  }
}

// Timestamp the trend chart plots a combo at. Prefer the upstream
// leanVM commit's author time (set on result files for historical-SHA
// sweeps where bench time ≠ code time); fall back to first_run_ts for
// every combo where the bench-then-commit cadence makes them ~equal.
function comboTimestamp(c) {
  return c && (c.leanvm_commit_ts || c.first_run_ts);
}

function comboShortLabel(c, withTime = true) {
  if (!c) return "no commit";
  const ls = `leanSig ${comboRef(c.leansig_branch, c.leansig_sha)}`;
  const lm = `leanVM ${comboRef(c.leanmultisig_branch, c.leanmultisig_sha)}`;
  return withTime
    ? `${lm} · ${ls}  —  ${fmtRelative(c.latest_run_ts)}`
    : `${lm} · ${ls}`;
}

function comboFullLabel(c) {
  if (!c) return "no commit";
  const ls = `leanSig ${comboRef(c.leansig_branch, c.leansig_sha, /*fullSha=*/true)}`;
  const lm = `leanVM ${comboRef(c.leanmultisig_branch, c.leanmultisig_sha, /*fullSha=*/true)}`;
  return `${lm} · ${ls}`;
}

// Render a ref as `<branch>@<sha>` when both are known, else fall back
// to whichever we have. Historical runs (pre-branch-tracking) have
// branch="unknown" and only get the SHA. api-xmss mode has no leansig
// dep at all and tags both as "n/a"; collapse to just `n/a` in that case.
function comboRef(branch, sha, fullSha = false) {
  const realSha = sha && sha !== "n/a";
  const realBranch = branch && branch !== "unknown";
  const s = fullSha ? (sha || "—") : shortSha(sha);
  if (realBranch && realSha) return `${branch}@${s}`;
  if (realBranch) return branch;
  if (realSha) return s;
  return "—";
}

function shortSha(s) { return s && s.length >= 8 ? s.slice(0, 8) : (s || "—"); }

// DOM version of comboShortLabel that turns each `branch@sha` into a
// GitHub link to that commit's tree. Use this where we render to DOM
// (dropdown options, trend table cells); fall back to comboShortLabel
// for text-only contexts like tooltips and Chart.js axis labels.
function comboLabelDom(c, withTime = true) {
  const frag = document.createDocumentFragment();
  if (!c) { frag.appendChild(document.createTextNode("no commit")); return frag; }
  frag.appendChild(document.createTextNode("leanVM "));
  frag.appendChild(repoRefLink("leanVM", c.leanmultisig_branch, c.leanmultisig_sha));
  frag.appendChild(document.createTextNode(" · leanSig "));
  frag.appendChild(repoRefLink("leanSig", c.leansig_branch, c.leansig_sha));
  if (withTime) {
    frag.appendChild(document.createTextNode(`  —  ${fmtRelative(c.latest_run_ts)}`));
  }
  return frag;
}

// Render `branch@sha` as an <a> linking to the GitHub tree at that
// commit. stopPropagation so a click on the link doesn't also bubble
// to a parent combo-option's select handler.
function repoRefLink(repo, branch, sha) {
  const display = comboRef(branch, sha);
  if (!sha || !/^[0-9a-f]{7,40}$/i.test(sha)) {
    return document.createTextNode(display);
  }
  return el("a", {
    href: `https://github.com/leanEthereum/${repo}/tree/${sha}`,
    target: "_blank",
    rel: "noopener",
    title: `${repo} ${sha}`,
    onclick: (e) => e.stopPropagation(),
  }, display);
}

function rerenderRunForCombo() {
  const machines = filteredMachines(indexData.machines || [], activeCombo);
  const runCount = machines.reduce((n, m) => n + m.runs.length, 0);

  document.querySelector("#stat-runs").textContent = runCount;
  document.querySelector("#stat-machines").textContent = machines.length;
  const latest = activeCombo ? activeCombo.latest_run_ts : indexData.generated_at;
  document.querySelector("#stat-generated").textContent = fmtDate(latest);

  // xmss.* workloads are leaf-level crypto primitives (sign / verify /
  // keygen). They run in microseconds and aren't useful for cross-machine
  // comparison or topology analysis — filter them out of the run page.
  const allWorkloads = new Set();
  for (const m of machines) for (const r of m.runs) for (const w of r.workloads || []) {
    if (!w.name.startsWith("xmss.")) allWorkloads.add(w.name);
  }

  const compare = document.querySelector("#compare-grid");
  compare.innerHTML = "";
  renderCompare(compare, [...allWorkloads], machines);

  const proofSizes = document.querySelector("#proof-size-grid");
  proofSizes.innerHTML = "";
  renderProofSizes(proofSizes, [...allWorkloads], machines);

  const scaling = document.querySelector("#scaling-grid");
  scaling.innerHTML = "";
  renderScaling(scaling, [...allWorkloads], machines);

  const list = document.querySelector("#machine-list");
  list.innerHTML = "";
  if (!machines.length) {
    list.appendChild(el("p", { text: "No runs match this commit." }));
  } else {
    for (const m of machines) list.appendChild(renderMachineCard(m));
  }
}

// Sort workload names so embedded numbers order numerically — flat_125 before
// flat_1000 — instead of lexicographically, where "1000" < "125" makes the
// card order jump around (1000, 125, 250, 500). Used wherever a group's cards
// are laid out.
const byNaturalName = (a, b) => a.localeCompare(b, undefined, { numeric: true });

// One chart per workload, grouped by category. leansig stays at the top
// level; aggregate.* is subdivided by second segment (flat / tree / split /
// merge) so the leanVM section breaks down into focused subsections.
// Unknown prefixes fall into an "other" bucket so new workloads render without
// code changes.
function renderCompare(container, workloadNames, machines) {
  const grouped = {};
  for (const name of workloadNames) {
    const [head, second = ""] = name.split(".");
    let key;
    if (head === "aggregate") {
      if (second.startsWith("flat_"))       key = "aggregate.flat";
      else if (second.startsWith("tree_"))  key = "aggregate.tree";
      else if (second.startsWith("deep_"))  key = "aggregate.deep";
      else if (second.startsWith("split_")) key = "aggregate.split";
      else if (second.startsWith("merge_")) key = "aggregate.merge";
      else                                  key = "aggregate.other";
    } else {
      key = head;
    }
    (grouped[key] = grouped[key] || []).push(name);
  }
  for (const v of Object.values(grouped)) v.sort(byNaturalName);

  const preferredOrder = [
    "leansig",
    "aggregate.flat", "aggregate.tree", "aggregate.deep", "aggregate.split", "aggregate.merge",
  ];
  const keys = [
    ...preferredOrder.filter((k) => grouped[k]),
    ...Object.keys(grouped).filter((k) => !preferredOrder.includes(k)).sort(),
  ];

  // Clarify which project each group belongs to. "aggregate.*" IS leanVM's
  // main deliverable so the subdivided groups carry the leanvm prefix.
  const displayLabel = (g) => ({
    leansig:             "leanSig",
    "aggregate.flat":    "leanVM.flat",
    "aggregate.tree":    "leanVM.tree",
    "aggregate.deep":    "Deep recursion",
    "aggregate.split":   "leanVM.split",
    "aggregate.merge":   "leanVM.merge",
    "aggregate.other":   "leanVM.other",
  }[g] || g);

  for (const group of keys) {
    const section = el("div", { class: "compare-group" },
      el("h3", { class: "compare-group-head", text: displayLabel(group) }),
    );
    // aggregate.tree's wall-clock bundles N × leaf aggregation + the recursion
    // step. That bundled number isn't a metric worth charting on its own, so we
    // skip the per-workload cards for this group and show only the recursion-only
    // time (root node) extracted from the per-iteration report.
    if (group === "aggregate.flat") {
      // Collapse the four per-leaf bar cards into one leaf-size sweep (x = leaf
      // size, one line per machine), mirroring the trend page's flat chart.
      // Falls back to the per-workload bars if the sweep can't be built (a
      // single leaf size, or no mean data on any machine).
      const flatCard = buildFlatLeafCard(grouped[group], machines);
      if (flatCard) {
        section.appendChild(flatCard);
      } else {
        const grid = el("div", { class: "compare-group-grid" });
        for (const wl of grouped[group]) grid.appendChild(buildCompareCard(wl, machines));
        section.appendChild(grid);
      }
    } else if (group !== "aggregate.tree" && group !== "aggregate.deep") {
      const grid = el("div", { class: "compare-group-grid" });
      for (const wl of grouped[group]) {
        grid.appendChild(buildCompareCard(wl, machines));
      }
      section.appendChild(grid);
    }
    if (group === "aggregate.deep") {
      section.appendChild(el("p", { class: "compare-group-note" },
        "Aggregation-strategy comparison for 1000 signatures: 2-level trees (8×125, 2×500) vs 3-level recursion (2×2×250, 2×4×125, 4×2×125). Total wall-clock per machine — lower is the cheaper strategy.",
      ));
      const grid = el("div", { class: "compare-group-grid" });
      appendDeepCharts(grid, machines);
      section.appendChild(grid);
    }
    if (group === "aggregate.tree") {
      section.appendChild(el("p", { class: "compare-group-note" },
        "aggregate.tree wall-clock bundles N × leaf aggregation + recursion, so it isn't charted directly. Shown below is the recursion-only time — the root node's time_secs from the per-iteration benchmark report.",
      ));
      const treeWorkloads = grouped[group].filter((n) => /\.tree_\d+x\d+_r2$/.test(n));
      if (treeWorkloads.length) {
        // Recursion-only shown as merged line sweeps (machines as lines), not
        // per-workload bar cards — mirrors the flat leaf-size sweep. Two
        // complementary cross-section views of the (fan-in × leaf-size) grid:
        // one fixes leaf size and varies fan-in, the other fixes fan-in and
        // varies leaf size. Each card shows machines as separate lines so
        // cross-CPU shape differences are visible at a glance.
        appendRecursionCrossSection(section, treeWorkloads, machines, "fanIn");
        appendRecursionCrossSection(section, treeWorkloads, machines, "leafSize");
      }
    }
    container.appendChild(section);
  }
}

// Run-page flat group as one chart: x = leaf size (raw XMSS sigs, log axis),
// one line per machine, y = best mean ms. The across-machines analog of the
// trend page's "leaf-size sweep". Returns a grid-wrapped card, or null when
// there's too little data (caller falls back to per-workload bars).
function buildFlatLeafCard(flatWorkloads, machines) {
  const parsed = flatWorkloads
    .map((name) => {
      const m = name.match(/^aggregate\.flat_(\d+)_r2$/);
      return m ? { name, leaf: parseInt(m[1], 10) } : null;
    })
    .filter(Boolean)
    .sort((a, b) => a.leaf - b.leaf);
  if (parsed.length < 2) return null;

  const bestMeanMs = (mach, workloadName) => {
    let best = null;
    for (const r of mach.runs || []) {
      const w = (r.workloads || []).find((x) => x.name === workloadName);
      if (w && w.mean_ns != null && (best == null || w.mean_ns < best)) best = w.mean_ns;
    }
    return best == null ? null : best / 1e6;
  };

  const datasets = [];
  machines.forEach((mach, i) => {
    const data = parsed.map((p) => {
      const ms = bestMeanMs(mach, p.name);
      return ms != null ? { x: p.leaf, y: ms } : null;
    }).filter(Boolean);
    if (data.length < 2) return;
    datasets.push({
      label: mach.label,
      data,
      borderColor: colorFor(i),
      backgroundColor: colorFor(i) + "22",
      tension: 0.15,
      fill: false,
      pointRadius: 4,
      pointHoverRadius: 6,
    });
  });
  if (!datasets.length) return null;

  const xValues = parsed.map((p) => p.leaf);
  const grid = el("div", { class: "compare-group-grid" });
  const card = el("div", { class: "compare-card" });
  card.appendChild(el("h3", { text: "leaf-size sweep" }));
  const wrap = el("div", { class: "compare-card-chart" });
  const canvas = el("canvas");
  wrap.appendChild(canvas);
  card.appendChild(wrap);
  grid.appendChild(card);

  queueMicrotask(() => {
    new Chart(canvas.getContext("2d"), {
      type: "line",
      data: { datasets },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: { display: true, position: "bottom", labels: { boxWidth: 12, padding: 8, font: { size: 11 } } },
          tooltip: {
            callbacks: {
              title: (items) => `leaf size: ${items[0].parsed.x} raw XMSS sigs`,
              label: (ctx) => `${ctx.dataset.label}: ${ctx.parsed.y.toFixed(0)} ms`,
            },
          },
        },
        scales: {
          x: {
            type: "logarithmic",
            title: { display: true, text: "leaf size (raw XMSS sigs)" },
            min: xValues[0],
            max: xValues[xValues.length - 1],
            afterBuildTicks: (axis) => { axis.ticks = xValues.map((v) => ({ value: v })); },
            ticks: { callback: (v) => v },
          },
          y: {
            type: yAxisType(),
            title: { display: true, text: "ms (mean)" },
            beginAtZero: !useLogScale,
          },
        },
      },
    });
  });
  return grid;
}

// Cross-section views of the (fan-in × leaf-size) grid. `varies` picks
// which axis is the chart's x-axis; the other axis becomes the slicer
// (one card per fixed value of it).
//
//   varies="fanIn"    → cards = leaf sizes; each card plots fan-in vs time
//   varies="leafSize" → cards = fan-ins; each card plots leaf size vs time
//
// Both produce small line charts with one line per machine.
function appendRecursionCrossSection(section, treeWorkloads, machines, varies) {
  const parsed = treeWorkloads
    .map((name) => {
      const m = name.match(/^aggregate\.tree_(\d+)x(\d+)_r2$/);
      if (!m) return null;
      return { name, fanIn: parseInt(m[1], 10), leafSize: parseInt(m[2], 10) };
    })
    .filter(Boolean);
  if (!parsed.length) return;

  const slicerKey   = varies === "fanIn" ? "leafSize" : "fanIn";
  const slicerLabel = varies === "fanIn" ? "leaf size" : "fan-in";
  const xLabel      = varies === "fanIn" ? "recursion fan-in" : "leaf size (raw XMSS sigs)";
  // Heading describes the chart axes; each card's own title (e.g.
  // "leaf size = 125") names the dimension being held fixed.
  const headingText = varies === "fanIn"
    ? "recursion-only time vs fan-in size"
    : "recursion-only time vs leaf size";

  const slicerValues = [...new Set(parsed.map((p) => p[slicerKey]))].sort((a, b) => a - b);
  if (!slicerValues.length) return;

  // First pass: build per-slicer datasets so we can share a y-axis ceiling
  // across the subgroup. With independent y-axes a small fan-in card and a
  // large fan-in card both look "flat" because each auto-zooms to its own
  // range — losing the absolute-magnitude story between cards.
  const built = [];
  for (const sv of slicerValues) {
    const row = parsed.filter((p) => p[slicerKey] === sv).sort((a, b) => a[varies] - b[varies]);
    if (row.length < 2) continue;
    const datasets = [];
    machines.forEach((mach, i) => {
      const data = row.map((p) => {
        const ns = recursionRootNs(mach, p.name);
        return ns != null ? { x: p[varies], y: ns / 1e6 } : null;
      }).filter(Boolean);
      if (data.length < 2) return;
      datasets.push({
        label: mach.label,
        data,
        borderColor: colorFor(i),
        backgroundColor: colorFor(i) + "22",
        tension: 0.15,
        fill: false,
        pointRadius: 4,
        pointHoverRadius: 6,
      });
    });
    if (!datasets.length) continue;
    built.push({ sv, row, datasets });
  }
  if (!built.length) return;

  const yMax = niceCeil(Math.max(
    ...built.flatMap((b) => b.datasets.flatMap((ds) => ds.data.map((p) => p.y))),
  ));

  const grid = el("div", { class: "compare-group-grid" });
  for (const b of built) {
    const xValues = b.row.map((p) => p[varies]);
    const card = el("div", { class: "compare-card" });
    card.appendChild(el("h3", { text: `${slicerLabel} = ${b.sv}` }));
    const wrap = el("div", { class: "compare-card-chart" });
    const canvas = el("canvas");
    wrap.appendChild(canvas);
    card.appendChild(wrap);
    grid.appendChild(card);

    queueMicrotask(() => {
      new Chart(canvas.getContext("2d"), {
        type: "line",
        data: { datasets: b.datasets },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          plugins: {
            legend: { display: false },
            tooltip: {
              callbacks: {
                title: (items) => `${xLabel}: ${items[0].parsed.x}`,
                label: (ctx) => `${ctx.dataset.label}: ${ctx.parsed.y.toFixed(0)} ms`,
              },
            },
          },
          scales: {
            x: {
              type: "logarithmic",
              title: { display: true, text: xLabel },
              min: xValues[0],
              max: xValues[xValues.length - 1],
              afterBuildTicks: (axis) => {
                axis.ticks = xValues.map((v) => ({ value: v }));
              },
              ticks: { callback: (v) => v },
            },
            y: {
              title: { display: true, text: "recursion-only ms (mean)" },
              beginAtZero: true,
              max: yMax,
            },
          },
        },
      });
    });
  }
  section.appendChild(el("h4", { class: "compare-subgroup-head", text: headingText }));
  section.appendChild(grid);
}

// ---- Deep-recursion charts (shared by the run page's "Deep recursion"
// group and the index page's "leanVM deep recursion" section). Every chart
// compares machines as separate series, matching the across-machines format
// used elsewhere on the run page.

// Parse `aggregate.deep_<root>x<mid>x<leaf>_r2` names into topology descriptors,
// sorted naturally so equal-size variants (2×4×125 / 4×2×125) sit adjacent.
// Curated aggregation-strategy comparison: a fixed set of topologies that all
// aggregate the same 1000 raw XMSS signatures, spanning 2-level trees and
// 3-level deep recursion. Order is meaningful and preserved on the x-axis.
const DEEP_TOPOLOGIES = [
  { name: "aggregate.tree_8x125_r2",   label: "8×125",   sigs: 1000, levels: 2 },
  { name: "aggregate.tree_2x500_r2",   label: "2×500",   sigs: 1000, levels: 2 },
  { name: "aggregate.deep_2x2x250_r2", label: "2×2×250", sigs: 1000, levels: 3 },
  { name: "aggregate.deep_2x4x125_r2", label: "2×4×125", sigs: 1000, levels: 3 },
  { name: "aggregate.deep_4x2x125_r2", label: "4×2×125", sigs: 1000, levels: 3 },
];

// Grouped bar: x = instance type (machine), one bar series per topology
// clustered within each instance. `valueMs(machine, row)` returns the metric
// in ms (or null when the machine never benched that topology).
function deepBarCard(rows, machines, title, valueMs, yLabel, fmt = (v) => v.toFixed(0)) {
  const present = machines.filter((m) => rows.some((p) => valueMs(m, p) != null));
  if (!present.length) return null;
  const labels = present.map((m) => m.label);
  const datasets = rows.map((p, i) => ({
    label: p.label,
    data: present.map((m) => valueMs(m, p)),
    backgroundColor: colorFor(i),
  }));

  const card = el("div", { class: "compare-card" });
  card.appendChild(el("h3", { text: title }));
  const wrap = el("div", { class: "compare-card-chart" });
  const canvas = el("canvas");
  wrap.appendChild(canvas);
  card.appendChild(wrap);

  queueMicrotask(() => {
    new Chart(canvas.getContext("2d"), {
      type: "bar",
      data: { labels, datasets },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: { display: true, position: "bottom", labels: { boxWidth: 12, padding: 8, font: { size: 11 } } },
          tooltip: { callbacks: { label: (ctx) => `${ctx.dataset.label}: ${fmt(ctx.parsed.y)} ${yLabel}` } },
        },
        scales: {
          x: { title: { display: true, text: "instance type" } },
          y: { type: yAxisType(), title: { display: true, text: yLabel }, beginAtZero: !useLogScale },
        },
      },
    });
  });
  return card;
}

// Build the curated comparison into `grid`. Returns true if anything was
// appended (callers hide the section header when not). Pulls from the full
// per-machine run data, so it spans both tree (2-level) and deep (3-level)
// workloads regardless of how the run page groups them.
function appendDeepCharts(grid, machines) {
  const totalMs = (mach, row) => {
    const ns = bestMeanNs(mach, row.name);
    return ns == null ? null : ns / 1e6;
  };

  // All entries aggregate the same 1000 signatures, so total wall-clock is the
  // direct strategy comparison — no per-signature normalization needed.
  const card = deepBarCard(DEEP_TOPOLOGIES, machines, "total time by topology", totalMs, "ms");
  if (!card) return false;
  grid.appendChild(card);
  return true;
}

// Proof-size section — one row per aggregate workload, showing root /
// mid / leaf KiB. Deterministic per topology, so we read off any one
// machine's run that recorded proof data. Older runs (pre-proof_kib) get
// "—" filler.
function renderProofSizes(container, workloadNames, machines) {
  const aggWorkloads = workloadNames.filter((n) => n.startsWith("aggregate.")).sort(byNaturalName);
  if (!aggWorkloads.length) return;

  const findProof = (workloadName) => {
    for (const m of machines) {
      for (const r of m.runs || []) {
        const w = (r.workloads || []).find((x) => x.name === workloadName);
        if (w && (w.proof_kib_root != null || w.proof_kib_by_path)) return w;
      }
    }
    return null;
  };

  const rows = aggWorkloads.map((name) => {
    const w = findProof(name);
    if (!w) return { name, root: null, leaf: null, mids: [] };
    const byPath = w.proof_kib_by_path || [];
    // Group sizes by depth, average each tier (intra-tier sizes should match).
    const byDepth = {};
    for (const e of byPath) {
      (byDepth[e.depth] = byDepth[e.depth] || []).push(e.kib);
    }
    const depths = Object.keys(byDepth).map(Number).sort((a, b) => a - b);
    const avg = (xs) => Math.round(xs.reduce((a, b) => a + b, 0) / xs.length);
    const root = w.proof_kib_root ?? (byDepth[0] ? avg(byDepth[0]) : null);
    const leaf = w.proof_kib_leaf ?? (depths.length
      ? avg(byDepth[depths[depths.length - 1]])
      : null);
    // Intermediate tiers: depths strictly between 0 and the deepest leaf.
    const mids = depths.length > 2
      ? depths.slice(1, -1).map((d) => ({ depth: d, kib: avg(byDepth[d]) }))
      : [];
    return { name, root, leaf, mids };
  });

  if (rows.every((r) => r.root == null && r.leaf == null)) {
    container.appendChild(el("p", { class: "section-note",
      text: "No proof-size data for this commit yet — re-run bench with the proof_kib-capturing runner to populate." }));
    return;
  }

  const table = el("table", { class: "proof-size-table" });
  const head = el("thead");
  head.appendChild(el("tr", {},
    el("th", { text: "workload" }),
    el("th", { text: "leaf" }),
    el("th", { text: "mid" }),
    el("th", { text: "root (published)" }),
  ));
  table.appendChild(head);
  const body = el("tbody");
  for (const r of rows) {
    const fmt = (k) => k == null ? "—" : `${k} KiB`;
    const midText = r.mids.length
      ? r.mids.map((m) => `${m.kib} KiB`).join(" · ")
      : (r.leaf != null && r.root != null && r.leaf !== r.root ? "—" : "—");
    body.appendChild(el("tr", {},
      el("td", { class: "proof-size-name", text: r.name }),
      el("td", { text: fmt(r.leaf) }),
      el("td", { text: midText }),
      el("td", { class: "proof-size-root", text: fmt(r.root) }),
    ));
  }
  table.appendChild(body);
  container.appendChild(table);
}

// Best (smallest) mean timing in ns for a workload on a machine, or null.
function bestMeanNs(machine, workloadName) {
  let best = null;
  for (const r of machine.runs || []) {
    const w = (r.workloads || []).find((x) => x.name === workloadName);
    if (w && w.mean_ns != null && (best == null || w.mean_ns < best)) best = w.mean_ns;
  }
  return best;
}

// One merged scaling card: x = logical cores (c4 family, log-spaced), one line
// per series entry. `valueMs(machine, name)` pulls the metric in ms (mean for
// flat, root time for recursion). `yMax` (optional) shares a ceiling across
// sibling cards. Respects the global log-scale toggle. Returns null if no
// series has ≥2 core points.
function buildMergedScalingCard({ title, yLabel, series, c4, valueMs, yMax }) {
  const xs = c4.map((m) => m.logical_cores);
  const datasets = [];
  series.forEach((s, i) => {
    const points = [];
    for (const m of c4) {
      const v = valueMs(m, s.name);
      if (v != null) points.push({ x: m.logical_cores, y: v });
    }
    if (points.length < 2) return;
    datasets.push({
      label: s.label,
      data: points,
      borderColor: colorFor(i),
      backgroundColor: colorFor(i) + "22",
      pointRadius: 4,
      pointHoverRadius: 6,
      tension: 0.15,
      fill: false,
    });
  });
  if (!datasets.length) return null;

  const card = el("div", { class: "compare-card" });
  card.appendChild(el("h3", { text: title }));
  const wrap = el("div", { class: "compare-card-chart" });
  const canvas = el("canvas");
  wrap.appendChild(canvas);
  card.appendChild(wrap);

  queueMicrotask(() => {
    new Chart(canvas.getContext("2d"), {
      type: "line",
      data: { datasets },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: { display: true, position: "bottom", labels: { boxWidth: 12, padding: 8, font: { size: 11 } } },
          tooltip: {
            callbacks: {
              title: (items) => `${items[0].parsed.x} logical cores`,
              label: (ctx) => `${ctx.dataset.label}: ${ctx.parsed.y.toFixed(ctx.parsed.y < 10 ? 3 : 0)} ms`,
            },
          },
        },
        scales: {
          x: {
            type: "logarithmic",
            title: { display: true, text: "logical cores (vCPU)" },
            min: xs[0],
            max: xs[xs.length - 1],
            afterBuildTicks: (axis) => { axis.ticks = xs.map((v) => ({ value: v })); },
            ticks: { callback: (v) => v },
          },
          y: {
            type: yAxisType(),
            title: { display: true, text: yLabel },
            beginAtZero: !useLogScale,
            ...(yMax != null && !useLogScale ? { max: yMax } : {}),
          },
        },
      },
    });
  });
  return card;
}

// Scaling section — for each workload, plot timing vs physical cores across
// the c4-standard-* family. Same Granite Rapids core, only the count changes,
// so the slope is a clean read on parallel scaling for that workload.
function renderScaling(container, workloadNames, machines) {
  const c4 = machines
    .filter((m) => /^c4-standard-\d+$/.test(m.label || ""))
    .filter((m) => m.logical_cores != null)
    .sort((a, b) => a.logical_cores - b.logical_cores);

  if (c4.length < 2) {
    container.appendChild(el("p", { class: "section-note",
      text: "Need at least 2 c4-standard-* machines for a scaling line; only " + c4.length + " for this commit." }));
    return;
  }

  const grouped = {};
  for (const name of workloadNames) {
    const prefix = name.split(".")[0];
    (grouped[prefix] = grouped[prefix] || []).push(name);
  }
  for (const v of Object.values(grouped)) v.sort(byNaturalName);

  const preferredOrder = ["leansig", "aggregate"];
  const keys = [
    ...preferredOrder.filter((k) => grouped[k]),
    ...Object.keys(grouped).filter((k) => !preferredOrder.includes(k)).sort(),
  ];
  const displayLabel = (g) => ({ leansig: "leanSig", aggregate: "leanVM" }[g] || g);

  for (const group of keys) {
    const section = el("div", { class: "compare-group" },
      el("h3", { class: "compare-group-head", text: displayLabel(group) }),
    );

    if (group === "aggregate") {
      // Flat: one merged leaf-size sweep (x = cores, one line per leaf size),
      // mirroring the across-machines flat sweep. Non-flat/non-tree aggregate
      // workloads (split / merge) stay as individual cards. Falls back to
      // per-workload flat cards if the merge can't be built.
      const grid = el("div", { class: "compare-group-grid" });
      const flatWls = grouped[group]
        .filter((n) => /^aggregate\.flat_\d+_r2$/.test(n)).sort(byNaturalName);
      const flatCard = buildMergedScalingCard({
        title: "leaf-size sweep",
        yLabel: "ms (mean)",
        series: flatWls.map((n) => ({ name: n, label: n.match(/flat_(\d+)_r2/)[1] })),
        c4,
        valueMs: (m, n) => { const ns = bestMeanNs(m, n); return ns == null ? null : ns / 1e6; },
      });
      if (flatCard) {
        grid.appendChild(flatCard);
      } else {
        for (const wl of flatWls) { const c = buildScalingCard(wl, c4); if (c) grid.appendChild(c); }
      }
      for (const wl of grouped[group].filter((n) =>
        !/^aggregate\.flat_\d+_r2$/.test(n) && !/\.tree_\d+x\d+_r2$/.test(n))) {
        const c = buildScalingCard(wl, c4);
        if (c) grid.appendChild(c);
      }
      section.appendChild(grid);

      // Recursion-only: one merged fan-in sweep per leaf size (x = cores, one
      // line per fan-in), sharing a y-ceiling across the leaf cards so absolute
      // magnitudes stay comparable.
      const treeParsed = grouped[group]
        .map((n) => {
          const m = n.match(/^aggregate\.tree_(\d+)x(\d+)_r2$/);
          return m ? { name: n, fanIn: +m[1], leaf: +m[2] } : null;
        })
        .filter(Boolean);
      if (treeParsed.length) {
        section.appendChild(el("h4", { class: "compare-subgroup-head", text: "recursion-only" }));
        const recMs = (m, n) => { const ns = recursionRootNs(m, n); return ns == null ? null : ns / 1e6; };
        const allY = treeParsed.flatMap((p) => recursionScalingPoints(p.name, c4).map((pt) => pt.y));
        const yMax = allY.length ? niceCeil(Math.max(...allY)) : undefined;
        const leaves = [...new Set(treeParsed.map((p) => p.leaf))].sort((a, b) => a - b);
        const recurGrid = el("div", { class: "compare-group-grid" });
        for (const leaf of leaves) {
          const series = treeParsed.filter((p) => p.leaf === leaf)
            .sort((a, b) => a.fanIn - b.fanIn)
            .map((p) => ({ name: p.name, label: `${p.fanIn}×` }));
          const card = buildMergedScalingCard({
            title: `fan-in sweep · ${leaf}-leaf`,
            yLabel: "ms (recursion-only)",
            series, c4, valueMs: recMs, yMax,
          });
          if (card) recurGrid.appendChild(card);
        }
        section.appendChild(recurGrid);
      }
    } else {
      const grid = el("div", { class: "compare-group-grid" });
      for (const wl of grouped[group]) {
        const card = buildScalingCard(wl, c4);
        if (card) grid.appendChild(card);
      }
      section.appendChild(grid);
    }
    container.appendChild(section);
  }
}

// Returns the best (smallest mean) recursion-only time in ns for a given
// tree workload on a machine, read directly off the root node's `time_secs`
// in the runner's per-iteration reports. Returns null when the machine has
// no run with raw report data — older runs without `time_ns_root` simply
// don't render in the recursion-only chart (no derivation fallback; the
// derived form `tree − N × flat` double-counts per-call setup overhead and
// gives a noisier, slightly biased number).
function recursionRootNs(machine, treeName) {
  let best = null;
  for (const r of machine.runs || []) {
    const w = (r.workloads || []).find((x) => x.name === treeName);
    if (w && w.time_ns_root != null && (best == null || w.time_ns_root < best)) {
      best = w.time_ns_root;
    }
  }
  return best;
}

function recursionScalingPoints(treeName, c4Machines) {
  const points = [];
  for (const mach of c4Machines) {
    const ns = recursionRootNs(mach, treeName);
    if (ns == null) continue;
    points.push({ x: mach.logical_cores, y: ns / 1e6 });
  }
  return points;
}

function buildScalingCard(workloadName, c4Machines) {
  const points = [];
  for (const m of c4Machines) {
    let best = null;
    for (const r of m.runs || []) {
      const w = (r.workloads || []).find((x) => x.name === workloadName);
      if (w && w.mean_ns != null && (best == null || w.mean_ns < best)) best = w.mean_ns;
    }
    if (best != null) points.push({ x: m.logical_cores, y: best / 1e6 });
  }
  if (points.length < 2) return null;

  const card = el("div", { class: "compare-card" });
  card.appendChild(el("h3", { text: workloadName }));
  const wrap = el("div", { class: "compare-card-chart" });
  const canvas = el("canvas");
  wrap.appendChild(canvas);
  card.appendChild(wrap);

  // log2 spacing for cores (2,4,8,16 land on integer ticks); keep
  // ms axis linear so the eye reads timing differences directly.
  queueMicrotask(() => {
    new Chart(canvas.getContext("2d"), {
      type: "line",
      data: {
        datasets: [{
          data: points,
          borderColor: "#4a46d9",
          backgroundColor: "#4a46d922",
          pointRadius: 4,
          pointHoverRadius: 6,
          tension: 0.15,
          fill: false,
        }],
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: { display: false },
          tooltip: {
            callbacks: {
              title: (items) => `${items[0].parsed.x} logical cores`,
              label: (ctx) => `${ctx.parsed.y.toFixed(3)} ms`,
            },
          },
        },
        scales: {
          x: {
            type: "logarithmic",
            title: { display: true, text: "logical cores (vCPU)" },
            min: points[0].x,
            max: points[points.length - 1].x,
            // Chart.js's default log ticks are decade-based (4,5,…,9,10,20,30),
            // so 16 never lands as a candidate. Replace the tick set with
            // exactly the data-point values so each c4 size gets its own label.
            afterBuildTicks: (axis) => {
              axis.ticks = points.map((p) => ({ value: p.x }));
            },
            ticks: { callback: (v) => v },
          },
          y: { title: { display: true, text: "ms (mean)" }, beginAtZero: true },
        },
      },
    });
  });
  return card;
}

function buildCompareCard(workloadName, machines) {
  const card = el("div", { class: "compare-card" });
  card.appendChild(el("h3", { text: workloadName }));
  const wrap = el("div", { class: "compare-card-chart" });
  const canvas = el("canvas");
  wrap.appendChild(canvas);
  card.appendChild(wrap);

  // Build per-machine entries first, THEN sort by speed (fastest first).
  // Color is bound to the machine's original list index so the same machine
  // keeps the same color across charts — only the ordering changes per chart.
  // Capture p5 + p95 alongside mean from the same "best run" so whiskers
  // correspond to that specific run, not a mix.
  const entries = [];
  for (const [i, m] of machines.entries()) {
    let best = null;
    let bestP5 = null;
    let bestP95 = null;
    for (const r of m.runs || []) {
      const w = (r.workloads || []).find((x) => x.name === workloadName);
      if (w && w.mean_ns != null && (best == null || w.mean_ns < best)) {
        best = w.mean_ns;
        bestP5 = w.p5_ns ?? null;
        bestP95 = w.p95_ns ?? null;
      }
    }
    if (best != null) {
      entries.push({
        label: m.label,
        value: best / 1e6,
        p5:  bestP5  != null ? bestP5  / 1e6 : null,
        p95: bestP95 != null ? bestP95 / 1e6 : null,
        color: colorFor(i),
      });
    }
  }
  entries.sort((a, b) => a.value - b.value);
  const labels = entries.map((e) => e.label);
  const values = entries.map((e) => e.value);
  const p5Values = entries.map((e) => e.p5);
  const p95Values = entries.map((e) => e.p95);
  const colors = entries.map((e) => e.color);

  // Force the x-axis to extend past the longest right whisker so p95 caps
  // never get clipped, and round up to a "nice" multiple of 1/2/2.5/5×10^k
  // so the axis ticks land on readable numbers (12 → 15, 377 → 400, etc.).
  const maxRight = Math.max(
    ...values,
    ...p95Values.filter((v) => v != null),
  );
  const xMax = niceCeil(maxRight);

  queueMicrotask(() => {
    new Chart(canvas.getContext("2d"), {
      type: "bar",
      data: {
        labels,
        datasets: [{
          data: values,
          backgroundColor: colors,
          borderRadius: 4,
          p5: p5Values,
          p95: p95Values,
        }],
      },
      options: {
        indexAxis: "y",
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: { display: false },
          tooltip: {
            callbacks: {
              // Multi-line tooltip — first line is the headline mean, then
              // p5/p95 only if we have them. Returning an array gives us
              // one DOM line per element.
              label: (ctx) => {
                const out = [`mean   ${ctx.parsed.x.toFixed(3)} ms  (best run)`];
                const p5 = p5Values[ctx.dataIndex];
                const p95 = p95Values[ctx.dataIndex];
                if (p5  != null) out.unshift(`p5     ${p5.toFixed(3)} ms`);
                if (p95 != null) out.push(`p95    ${p95.toFixed(3)} ms`);
                return out;
              },
            },
          },
        },
        scales: {
          x: { title: { display: true, text: "ms" }, beginAtZero: true, max: xMax },
          y: { ticks: { font: { family: getComputedStyle(document.body).getPropertyValue("--mono") } } },
        },
      },
      plugins: [variancePlugin],
    });
  });
  return card;
}

// Draws a horizontal whisker on each bar — leftward from p5 to mean, and
// rightward from mean to p95, each with a small cap. Lives outside per-
// chart code so it's registered once per Chart instance via `plugins:`.
// p5 / p95 values are passed in via `dataset.p5` and `dataset.p95`.
const variancePlugin = {
  id: "variance",
  afterDatasetDraw(chart, args) {
    const { ctx } = chart;
    const meta = chart.getDatasetMeta(args.index);
    const dataset = chart.data.datasets[args.index];
    const p5s  = dataset.p5;
    const p95s = dataset.p95;
    if (!Array.isArray(p5s) && !Array.isArray(p95s)) return;

    const dark = matchMedia("(prefers-color-scheme: dark)").matches;
    ctx.save();
    ctx.lineCap = "round";
    ctx.lineWidth = 1;
    ctx.strokeStyle = dark ? "rgba(240, 240, 234, 0.85)" : "rgba(26, 26, 26, 0.75)";

    const drawSegment = (x1, x2, y, cap) => {
      ctx.beginPath();
      ctx.moveTo(x1, y);
      ctx.lineTo(x2, y);
      ctx.moveTo(x2, y - cap);
      ctx.lineTo(x2, y + cap);
      ctx.stroke();
    };

    meta.data.forEach((bar, i) => {
      const meanX = bar.x;
      const y = bar.y;
      const cap = Math.min(7, (bar.height ?? 12) * 0.4);

      // Right whisker: mean → p95 (lives on chart background)
      const p95 = (p95s || [])[i];
      if (p95 != null) {
        const p95X = chart.scales.x.getPixelForValue(p95);
        if (p95X > meanX) drawSegment(meanX, p95X, y, cap);
      }

      // Left whisker: p5 → mean (lives on top of the colored bar fill)
      const p5 = (p5s || [])[i];
      if (p5 != null) {
        const p5X = chart.scales.x.getPixelForValue(p5);
        if (p5X < meanX) drawSegment(meanX, p5X, y, cap);
      }
    });

    ctx.restore();
  },
};

// Approximate on-demand list price (USD/hour) for the GCP machine types
// in the default remote-bench matrix, us-central1, as of 2026-04. Used
// only for a "≈$N/mo" hint on machine cards — not sustained-use or
// committed-use discounted, so treat as upper bound. Local machines (no
// matching key) get no cost shown.
const GCP_USD_PER_HOUR = {
  "n1-standard-4":   0.190,
  "c4-standard-4":   0.210,
  "c4-standard-8":   0.420,
  "c4-standard-16":  0.840,
  "c4-standard-32":  1.680,
};
const HOURS_PER_MONTH = 730;

const fmtMonthly = (label) => {
  const hourly = GCP_USD_PER_HOUR[label];
  if (hourly == null) return null;
  const monthly = Math.round(hourly * HOURS_PER_MONTH);
  return {
    short: `≈$${monthly.toLocaleString()}/mo`,
    title: `GCP ${label} · us-central1 on-demand · $${hourly.toFixed(3)}/hr × ${HOURS_PER_MONTH} h ≈ $${monthly}/mo (no SUD/CUD applied)`,
  };
};

function renderMachineCard(m) {
  const card = el("div", { class: "machine-card" });
  const cost = fmtMonthly(m.label);
  const metaText = `${m.cpu_model || ""} · ${m.physical_cores ?? "?"}p / ${m.logical_cores ?? "?"}l · ${m.memory_gb ?? "?"} GB · ${m.os || ""}`;
  const meta = el("div", { class: "machine-meta" }, metaText);
  if (cost) {
    meta.appendChild(document.createTextNode(" · "));
    meta.appendChild(el("span", { class: "machine-cost", title: cost.title, text: cost.short }));
  }
  card.appendChild(el("div", { class: "machine-head" },
    el("h3", { text: m.label || m.fingerprint }),
    meta,
  ));
  const runs = el("div", { class: "run-list" });
  for (const r of m.runs || []) {
    const link = el("a", {
      class: "run-item",
      href: `result.html?file=${encodeURIComponent(r.file)}`,
    },
      el("div", { class: "run-ts", text: fmtDate(r.timestamp) }),
      el("div", { text: `${(r.workloads || []).length} workload(s)` }),
    );
    runs.appendChild(link);
  }
  card.appendChild(runs);
  return card;
}


let indexAnnotations = []; // loaded from trend-annotations.json on first render

// --- index page: workload progression across combos ------------------
//
// Branch dropdown + machine selector. Each chart traces a single line:
// the filtered branch's combos plotted at `leanvm_commit_ts` if present
// (the upstream commit's author time) else `first_run_ts` as fallback —
// proxies for when
// the SHA landed on the branch — stable across re-benches, unlike
// `latest_run_ts`). "any branch" merges every combo into one line.
// Charts grouped by category mirror the run page's compare grouping.

// `metric` selects which per-workload field the trend plots (default mean_ns).
// `group` overrides the category a headline lands in (default derived from the
// workload name). The recursion-only headlines reuse the tree workloads but
// read `time_ns_root` — the root node's own time, i.e. the recursion step with
// leaf aggregation excluded — and file under their own `recursion` group.
const INDEX_HEADLINES = [
  { name: "aggregate.flat_125_r2",                         label: "flat_125" },
  { name: "aggregate.flat_250_r2",                         label: "flat_250" },
  { name: "aggregate.flat_500_r2",                         label: "flat_500" },
  { name: "aggregate.flat_1000_r2",                        label: "flat_1000" },
  { name: "aggregate.tree_2x125_r2", label: "tree_2x125", metric: "time_ns_root", group: "recursion" },
  { name: "aggregate.tree_4x125_r2", label: "tree_4x125", metric: "time_ns_root", group: "recursion" },
  { name: "aggregate.tree_8x125_r2", label: "tree_8x125", metric: "time_ns_root", group: "recursion" },
  { name: "aggregate.tree_2x250_r2", label: "tree_2x250", metric: "time_ns_root", group: "recursion" },
  { name: "aggregate.tree_4x250_r2", label: "tree_4x250", metric: "time_ns_root", group: "recursion" },
  { name: "aggregate.tree_8x250_r2", label: "tree_8x250", metric: "time_ns_root", group: "recursion" },
  { name: "aggregate.tree_2x500_r2", label: "tree_2x500", metric: "time_ns_root", group: "recursion" },
  { name: "aggregate.tree_4x500_r2", label: "tree_4x500", metric: "time_ns_root", group: "recursion" },
  { name: "aggregate.tree_8x500_r2", label: "tree_8x500", metric: "time_ns_root", group: "recursion" },
  { name: "aggregate.split_2x500_r2",                      label: "split_2x500" },
  { name: "aggregate.merge_split_and_original_2x500_r2",   label: "merge_split_and_original_2x500" },
  { name: "aggregate.merge_split_and_leaves_2x500x500_r2", label: "merge_split_and_leaves_2x500x500" },
];

const INDEX_GROUP_ORDER = ["flat", "recursion", "tree", "split", "merge", "other"];
const INDEX_GROUP_LABEL = {
  flat:      "leanVM.flat",
  recursion: "leanVM.recursion",
  tree:      "leanVM.tree",
  split:     "leanVM.split",
  merge:     "leanVM.merge",
  other:     "leanVM.other",
};

// EXPERIMENT: groups listed here collapse their headlines into multi-line
// charts instead of one card each.
//   yLabel    — y-axis title (metric being plotted)
//   cardTitle(key) — chart heading; `key` is the split value (or undefined)
//   lineLabel(h)   — legend/tooltip label per line
//   splitBy(h)     — optional: partition the group into one card per key
//                    (e.g. recursion → one fan-in sweep per leaf size)
const COMBINED_GROUPS = {
  flat: {
    yLabel:    "ms (mean)",
    cardTitle: () => "leaf-size sweep",
    lineLabel: (h) => h.label.replace(/^[a-z]+_/, ""),         // "flat_125" → "125"
  },
  recursion: {
    yLabel:    "ms (recursion-only)",
    splitBy:   (h) => Number(h.name.match(/_\d+x(\d+)_r2$/)[1]),
    cardTitle: (leaf) => `fan-in sweep · ${leaf}-leaf`,
    lineLabel: (h) => `${h.name.match(/_(\d+)x\d+_r2$/)[1]}×`,  // "tree_2x125" → "2×"
  },
};

function indexHeadlineGroup(name) {
  const second = name.startsWith("aggregate.") ? name.slice("aggregate.".length) : "";
  if (second.startsWith("flat_"))  return "flat";
  if (second.startsWith("tree_"))  return "tree";
  if (second.startsWith("split_")) return "split";
  if (second.startsWith("merge_")) return "merge";
  return "other";
}

// Branch filter default comes from site/config.json (default_leanvm_branch).
// `null` means "all branches".
let indexActiveLeanvmBranch = null;
let indexBranchCharts = [];

async function renderIndex() {
  let data;
  try {
    data = await fetch("results/index.json").then((r) => r.json());
  } catch (e) {
    document.querySelector("#branch-trend-section").innerHTML =
      `<p>No results yet. Run <code>uv run bench</code>, commit, push, and the
       site will populate.</p>`;
    return;
  }
  // Annotations are editable from site/trend-annotations.json without touching
  // code. Missing or malformed file → just render no annotations.
  try {
    const r = await fetch("trend-annotations.json");
    if (r.ok) indexAnnotations = await r.json();
  } catch (e) { /* ignore */ }

  const combos = data.combos || [];
  const machines = visibleMachines(data.machines).sort((a, b) =>
    (b.logical_cores || 0) - (a.logical_cores || 0));
  if (!combos.length || !machines.length) {
    document.querySelector("#branch-trend-section").innerHTML =
      "<p>No combos or machines in the index yet.</p>";
    return;
  }

  // Initial branch: URL > config default > all branches. Fall back to
  // "all branches" if the chosen branch isn't present in the data so
  // the page never starts empty.
  const cfg = await loadLeanBenchConfig();
  const urlBranch = new URLSearchParams(location.search).get("leanmultisig_branch");
  const branches = [...new Set(combos.map((c) => c.leanmultisig_branch).filter(Boolean))];
  const initial = urlBranch ?? cfg.default_leanvm_branch ?? null;
  indexActiveLeanvmBranch = (initial && branches.includes(initial)) ? initial : null;

  setupIndexBranchFilter(combos, machines);
  setupIndexMachineSelector(machines, combos);
  wireLogToggle(() => {
    recomputeBranchTrends(machines, combos);
    renderDeepRecursionSection(machines, combos);
  });
  recomputeBranchTrends(machines, combos);
  renderDeepRecursionSection(machines, combos);
}

// Index-page "Deep recursion" section: the same across-machines comparison as
// the run page. The curated set mixes tree (2-level) and deep (3-level)
// workloads, so it's only valid within a single leanVM pin — pick the most
// recent combo that actually has the deep workloads benched, scope every
// machine's runs to it, and label the section with that pin. Hidden when no
// deep run exists yet.
function renderDeepRecursionSection(machines, combos) {
  const section = document.querySelector("#deep-recursion-section");
  const grid = document.querySelector("#deep-recursion-grid");
  if (!section || !grid) return;
  grid.innerHTML = "";

  const deepNames = new Set(DEEP_TOPOLOGIES.filter((t) => t.levels >= 3).map((t) => t.name));
  const comboHasDeep = (combo) => machines.some((m) =>
    (m.runs || []).some((r) => runMatchesCombo(r, combo)
      && (r.workloads || []).some((w) => deepNames.has(w.name))));
  const combo = [...(combos || [])]
    .sort((a, b) => (b.latest_run_ts || "").localeCompare(a.latest_run_ts || ""))
    .find(comboHasDeep);

  const any = combo && appendDeepCharts(grid, filteredMachines(machines, combo));
  section.style.display = any ? "" : "none";

  const pinEl = document.querySelector("#deep-recursion-pin");
  if (pinEl) {
    pinEl.textContent = combo
      ? `leanVM ${combo.leanmultisig_branch}@${(combo.leanmultisig_sha || "").slice(0, 8)}`
      : "";
  }
}

function setupIndexBranchFilter(combos, machines) {
  const select = document.querySelector("#branch-filter-leanvm");
  if (!select) return;
  const branches = [...new Set(combos.map((c) => c.leanmultisig_branch).filter(Boolean))].sort();
  select.innerHTML = "";
  select.appendChild(new Option("all branches", "", false, indexActiveLeanvmBranch === null));
  for (const v of branches) {
    select.appendChild(new Option(v, v, false, v === indexActiveLeanvmBranch));
  }
  select.onchange = () => {
    indexActiveLeanvmBranch = select.value || null;
    syncIndexBranchToUrl();
    recomputeBranchTrends(machines, combos);
  };
}

function syncIndexBranchToUrl() {
  const params = new URLSearchParams(location.search);
  if (indexActiveLeanvmBranch) params.set("leanmultisig_branch", indexActiveLeanvmBranch);
  else params.delete("leanmultisig_branch");
  const search = params.toString();
  history.replaceState(null, "", location.pathname + (search ? "?" + search : "") + location.hash);
}

function setupIndexMachineSelector(machines, combos) {
  const select = document.querySelector("#branch-trend-machine");
  select.innerHTML = "";
  // Two GCP n1 VMs can land on different CPU generations (Skylake vs
  // Broadwell) and surface as separate fingerprints under the same
  // `--label`. Suffix with a fingerprint prefix only when the label
  // collides so non-ambiguous machines stay clean.
  const labelCount = new Map();
  for (const m of machines) {
    const label = m.label || m.fingerprint;
    labelCount.set(label, (labelCount.get(label) || 0) + 1);
  }
  for (const m of machines) {
    const label = m.label || m.fingerprint;
    const text = labelCount.get(label) > 1
      ? `${label} (${m.fingerprint.slice(0, 8)})`
      : label;
    select.appendChild(el("option", { value: m.fingerprint }, text));
  }
  select.onchange = () => recomputeBranchTrends(machines, combos);
}

function recomputeBranchTrends(machines, combos) {
  const machineSelect = document.querySelector("#branch-trend-machine");
  const machine = machines.find((m) => m.fingerprint === machineSelect.value) || machines[0];

  // best (ms) for a given (combo, workload) on this machine. `metric` picks the
  // per-workload ns field — mean_ns for total timing, time_ns_root for the
  // recursion-only (root node) series.
  const best = (combo, workloadName, metric = "mean_ns") => {
    const runs = (machine.runs || []).filter((r) =>
      r.git_shas.leansig_sha === combo.leansig_sha
      && r.git_shas.leanmultisig_sha === combo.leanmultisig_sha);
    let m = null;
    for (const r of runs) {
      const w = (r.workloads || []).find((x) => x.name === workloadName);
      const v = w?.[metric];
      if (v != null && (m == null || v < m)) m = v;
    }
    return m == null ? null : m / 1e6;
  };

  const filtered = indexActiveLeanvmBranch
    ? combos.filter((c) => c.leanmultisig_branch === indexActiveLeanvmBranch)
    : combos;
  // Group by leanVM branch then sort each group chronologically. Single-
  // branch mode collapses to one group; "all branches" keeps them
  // separate so each branch's progress reads as its own line.
  const byBranch = {};
  for (const c of filtered) {
    const b = c.leanmultisig_branch || "unknown";
    (byBranch[b] = byBranch[b] || []).push(c);
  }
  for (const arr of Object.values(byBranch)) {
    arr.sort((a, b) => (comboTimestamp(a) || "").localeCompare(comboTimestamp(b) || ""));
  }
  const branchNames = Object.keys(byBranch).sort();

  // Annotation resolution scope: visible combos only. An annotation whose combo
  // isn't in the current filter just doesn't render.
  const visibleCombos = filtered;
  // Resolve each annotation entry to a combo in the current scope. The
  // tooltip looks up by leanmultisig_sha so we can fold the annotation
  // text in when the user hovers a point that has one.
  const annotationByLm = new Map();
  for (const m of (indexAnnotations || [])) {
    const combo = visibleCombos.find((c) =>
      c.leanmultisig_sha
      && c.leanmultisig_sha.startsWith(m.from_leanmultisig_sha || ""));
    if (combo) annotationByLm.set(combo.leanmultisig_sha, m.label);
  }

  renderBranchTrendCharts(machine, byBranch, branchNames, best, annotationByLm);
}

function renderBranchTrendCharts(machine, byBranch, branchNames, best, annotationByLm) {
  const container = document.querySelector("#branch-trend-grid");
  for (const c of indexBranchCharts) c.destroy();
  indexBranchCharts = [];
  container.innerHTML = "";

  // Lazily create one section per category as charts arrive; keeps the
  // section ordering deterministic via INDEX_GROUP_ORDER.
  const subgroupGrids = {};
  const ensureSubgroupGrid = (g) => {
    if (subgroupGrids[g]) return subgroupGrids[g];
    const section = el("div", { class: "compare-group" },
      el("h3", { class: "compare-group-head", text: INDEX_GROUP_LABEL[g] || g }),
    );
    if (g === "recursion") {
      section.appendChild(el("p", { class: "compare-group-note" },
        "Recursion-only time — the root node's time_secs from the per-iteration benchmark report, with leaf aggregation excluded. Lower is better.",
      ));
    }
    const grid = el("div", { class: "compare-group-grid" });
    section.appendChild(grid);
    section.dataset.group = g;
    container.appendChild(section);
    subgroupGrids[g] = grid;
    return grid;
  };

  // Stable branch → colour map; same hue for the same branch across all
  // charts on the page.
  const colorForBranch = (br) => colorFor(branchNames.indexOf(br));

  // Shared x-axis range across every chart on the page. Computed from the
  // visible-commit set so charts at the same vertical position read against
  // the same dates, regardless of which workloads have which data points.
  const allTimes = [];
  for (const br of branchNames) {
    for (const c of byBranch[br]) {
      const t = comboTimestamp(c);
      if (t) allTimes.push(new Date(t).getTime());
    }
  }
  let xMin = null, xMax = null;
  if (allTimes.length) {
    xMin = Math.min(...allTimes);
    xMax = Math.max(...allTimes);
    // Pad ~3% on each side so the leftmost/rightmost points don't sit on
    // the chart edge and annotation badges have room to draw.
    const span = xMax - xMin || 86_400_000; // 1 day if everything's identical
    xMin -= span * 0.03;
    xMax += span * 0.03;
  }

  let any = false;

  // EXPERIMENT: render COMBINED_GROUPS as multi-line charts before the per-card
  // loop, then skip those headlines below. Branch scope is flattened — combos
  // across branches merged chronologically, lines colored per variant — so the
  // combined view reads cleanly in the default single-branch case. Groups with
  // a `splitBy` fan out into one card per split key (e.g. recursion → one
  // fan-in sweep per leaf size).
  const combinedHandled = new Set();
  const flatCombos = branchNames
    .flatMap((br) => byBranch[br])
    .sort((a, b) => (comboTimestamp(a) || "").localeCompare(comboTimestamp(b) || ""));

  const drawCombinedCard = (g, cfg, title, headlines) => {
    const datasets = [];
    headlines.forEach((h, i) => {
      const data = flatCombos
        .map((c) => {
          const ms = best(c, h.name, h.metric);
          if (ms == null) return null;
          return { x: new Date(comboTimestamp(c)).getTime(), y: ms, combo: c };
        })
        .filter((p) => p != null);
      if (!data.length) return;
      datasets.push({
        label: cfg.lineLabel(h),
        data,
        borderColor: colorFor(i),
        backgroundColor: colorFor(i) + "22",
        tension: 0.15,
        fill: false,
        pointRadius: 3,
        pointHoverRadius: 6,
        spanGaps: true,
      });
    });

    const card = el("div", { class: "compare-card" });
    card.appendChild(el("h3", { text: title }));
    const wrap = el("div", { class: "compare-card-chart" });
    card.appendChild(wrap);
    ensureSubgroupGrid(g).appendChild(card);
    if (!datasets.length) {
      wrap.appendChild(el("p", { class: "compare-empty", text: "no data on this machine" }));
      return;
    }
    any = true;
    const canvas = el("canvas");
    wrap.appendChild(canvas);
    queueMicrotask(() => {
      const titleStyle = { display: true, color: "rgba(128,128,128,0.7)", font: { size: 11, weight: "normal" } };
      const chart = new Chart(canvas.getContext("2d"), {
        type: "line",
        data: { datasets },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          parsing: false,
          plugins: {
            legend: { display: true, position: "bottom", labels: { boxWidth: 12, padding: 8, font: { size: 11 } } },
            tooltip: {
              callbacks: {
                title: (items) => {
                  const c = items[0].raw.combo;
                  return `leanVM ${comboRef(c.leanmultisig_branch, c.leanmultisig_sha)} · leanSig ${comboRef(c.leansig_branch, c.leansig_sha)}`;
                },
                label: (ctx) => {
                  const ms = ctx.parsed.y;
                  const str = ms < 1000 ? `${ms.toFixed(0)} ms` : `${(ms / 1000).toFixed(2)} s`;
                  return `${ctx.dataset.label}: ${str}`;
                },
              },
            },
          },
          scales: {
            x: {
              type: "linear",
              min: xMin ?? undefined,
              max: xMax ?? undefined,
              title: { ...titleStyle, text: "commit date (UTC)" },
              ticks: { callback: (v) => new Date(v).toISOString().slice(0, 10), maxTicksLimit: 6 },
            },
            y: { type: yAxisType(), title: { ...titleStyle, text: cfg.yLabel }, beginAtZero: !useLogScale },
          },
        },
      });
      indexBranchCharts.push(chart);
    });
  };

  for (const g of INDEX_GROUP_ORDER) {
    const cfg = COMBINED_GROUPS[g];
    if (!cfg) continue;
    const hs = INDEX_HEADLINES.filter((h) => (h.group || indexHeadlineGroup(h.name)) === g);
    if (!hs.length) continue;
    combinedHandled.add(g);

    if (!cfg.splitBy) {
      drawCombinedCard(g, cfg, cfg.cardTitle(), hs);
      continue;
    }
    // One card per split key, keys in ascending order.
    const buckets = new Map();
    for (const h of hs) {
      const k = cfg.splitBy(h);
      if (!buckets.has(k)) buckets.set(k, []);
      buckets.get(k).push(h);
    }
    const keys = [...buckets.keys()].sort((a, b) =>
      (typeof a === "number" && typeof b === "number") ? a - b : String(a).localeCompare(String(b)));
    for (const k of keys) drawCombinedCard(g, cfg, cfg.cardTitle(k), buckets.get(k));
  }

  for (const h of INDEX_HEADLINES) {
    if (combinedHandled.has(h.group || indexHeadlineGroup(h.name))) continue;
    const datasets = [];
    for (const br of branchNames) {
      const data = byBranch[br]
        .map((c) => {
          const ms = best(c, h.name, h.metric);
          if (ms == null) return null;
          return { x: new Date(comboTimestamp(c)).getTime(), y: ms, combo: c };
        })
        .filter((p) => p != null);
      if (!data.length) continue;
      datasets.push({
        label: br,
        data,
        borderColor: colorForBranch(br),
        backgroundColor: colorForBranch(br) + "22",
        tension: 0.15,
        fill: false,
        pointRadius: 4,
        pointHoverRadius: 6,
        spanGaps: true,
      });
    }

    const card = el("div", { class: "compare-card" });
    card.appendChild(el("h3", { text: h.label }));
    const wrap = el("div", { class: "compare-card-chart" });
    card.appendChild(wrap);
    ensureSubgroupGrid(h.group || indexHeadlineGroup(h.name)).appendChild(card);

    if (!datasets.length) {
      wrap.appendChild(el("p", { class: "compare-empty",
        text: "no data on this machine" }));
      continue;
    }
    any = true;

    const canvas = el("canvas");
    wrap.appendChild(canvas);

    // Single-branch view doesn't need an in-chart legend (the dropdown
    // label is the legend). Multi-branch shows branch names below.
    const showLegend = datasets.length > 1;

    queueMicrotask(() => {
      const titleStyle = {
        display: true,
        color: "rgba(128,128,128,0.7)",
        font: { size: 11, weight: "normal" },
      };
      const chart = new Chart(canvas.getContext("2d"), {
        type: "line",
        data: { datasets },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          parsing: false,
          plugins: {
            legend: {
              display: showLegend,
              position: "bottom",
              labels: { boxWidth: 12, padding: 8, font: { size: 11 } },
            },
            tooltip: {
              displayColors: false,
              callbacks: {
                title: (items) => {
                  const c = items[0].raw.combo;
                  return `leanVM ${comboRef(c.leanmultisig_branch, c.leanmultisig_sha)} · leanSig ${comboRef(c.leansig_branch, c.leansig_sha)}`;
                },
                label: (ctx) => {
                  const ms = ctx.parsed.y;
                  const day = new Date(ctx.parsed.x).toISOString().slice(0, 10);
                  const str = ms < 1000 ? `${ms.toFixed(0)} ms` : `${(ms / 1000).toFixed(2)} s`;
                  const lines = [];
                  const note = annotationByLm.get(ctx.raw.combo.leanmultisig_sha);
                  if (note) {
                    lines.push(...wrapAnnotationLines(note), "");
                  }
                  lines.push(`${day}: ${str}`);
                  return lines;
                },
              },
            },
          },
          scales: {
            x: {
              type: "linear",
              min: xMin ?? undefined,
              max: xMax ?? undefined,
              title: { ...titleStyle, text: "commit date (UTC)" },
              ticks: {
                callback: (v) => new Date(v).toISOString().slice(0, 10),
                maxTicksLimit: 6,
              },
            },
            y: {
              title: { ...titleStyle, text: "ms (mean)" },
              beginAtZero: true,
            },
          },
        },
      });
      indexBranchCharts.push(chart);

    });
  }
  if (!any) {
    container.innerHTML = "<p>No headline-workload data on this machine in the current branch scope.</p>";
  }
}

// Soft-wrap a long annotation label into shorter lines that fit inside
// the tooltip's max width (chart cards are ~320 px → ~38 mono-glyphs
// before Chart.js clips the tooltip against the canvas edge). Word-
// aware so we don't split mid-token.
function wrapAnnotationLines(text, width = 38) {
  const words = String(text).split(/\s+/);
  const out = [];
  let cur = "";
  for (const w of words) {
    if (!cur.length) { cur = w; continue; }
    if (cur.length + 1 + w.length <= width) { cur += " " + w; continue; }
    out.push(cur);
    cur = w;
  }
  if (cur.length) out.push(cur);
  return out;
}


async function renderResult() {
  const params = new URLSearchParams(location.search);
  const file = params.get("file");
  if (!file) {
    document.querySelector("#result-title").textContent = "no result selected";
    return;
  }

  const rawHref = `results/${file}`;
  document.querySelector("#raw-link").href = rawHref;

  let rec;
  try {
    rec = await fetch(rawHref).then((r) => r.json());
  } catch (e) {
    document.querySelector("#result-title").textContent = "failed to load";
    return;
  }

  document.querySelector("#result-title").textContent = rec.machine?.label || rec.run_id;
  document.querySelector("#result-subtitle").textContent = fmtDate(rec.timestamp);

  const spec = document.querySelector("#spec-grid");
  spec.className = "grid";
  const m = rec.machine || {};
  for (const [k, v] of [
    ["CPU", m.cpu_model],
    ["Arch", m.cpu_arch],
    ["Cores", `${m.physical_cores ?? "?"} physical / ${m.logical_cores ?? "?"} logical`],
    ["Memory", `${m.memory_gb ?? "?"} GB`],
    ["OS", m.os],
    ["Kernel", m.kernel],
    ["Fingerprint", m.fingerprint],
  ]) {
    if (v == null) continue;
    spec.appendChild(el("dt", { text: k }));
    spec.appendChild(el("dd", { text: String(v) }));
  }

  const prov = document.querySelector("#prov-grid");
  prov.className = "grid";
  const t = rec.toolchain || {};
  // GitHub `tree/<sha>` shows the working dir at that commit — better than
  // `commit/<sha>` which shows just the diff. Both SHAs are pinned to the
  // upstream leanEthereum repos via workloads/Cargo.toml.
  const treeBase = (repo) => `https://github.com/leanEthereum/${repo}/tree/`;
  const provEntries = [
    ["rustc",               t.rustc, null],
    ["leanSig branch",      t.branches?.leansig_branch,   null],
    ["leanSig SHA",         t.git_shas?.leansig_sha,      treeBase("leanSig")],
    ["leanVM branch",       t.branches?.leanmultisig_branch, null],
    ["leanVM SHA",          t.git_shas?.leanmultisig_sha, treeBase("leanVM")],
    ["Run ID",              rec.run_id, null],
    ["Notes",               rec.notes, null],
  ];
  for (const [k, v, urlBase] of provEntries) {
    if (!v) continue;
    prov.appendChild(el("dt", { text: k }));
    if (urlBase && /^[0-9a-f]{7,40}$/i.test(String(v))) {
      const dd = el("dd");
      dd.appendChild(el("a", {
        href: urlBase + v,
        target: "_blank",
        rel: "noopener noreferrer",
        text: String(v),
      }));
      prov.appendChild(dd);
    } else {
      prov.appendChild(el("dd", { text: String(v) }));
    }
  }

  const list = document.querySelector("#workload-list");
  // xmss.* workloads are gone from the codebase but historical result
  // files still carry them — hide so the UI stays in sync with the
  // current workload set.
  const workloads = (rec.workloads || []).filter((w) => !w.name.startsWith("xmss."));
  for (const [i, w] of workloads.entries()) {
    list.appendChild(renderWorkload(w, i));
  }
}

function renderWorkload(w, idx) {
  const card = el("div", { class: "workload" });
  const t = w.timing || {};
  card.appendChild(el("div", { class: "workload-head" },
    el("h3", { class: "workload-name", text: w.name || "?" }),
    el("div", { class: "workload-headline", text: fmtNs(t.mean_ns) }),
  ));

  const stats = el("div", { class: "workload-stats" });
  for (const [label, value] of [
    ["n",      t.n],
    ["min",    fmtNs(t.min_ns)],
    ["p50",    fmtNs(t.p50_ns)],
    ["mean",   fmtNs(t.mean_ns)],
    ["p95",    fmtNs(t.p95_ns)],
    ["max",    fmtNs(t.max_ns)],
    ["stddev", fmtNs(t.stddev_ns)],
  ]) {
    if (value == null) continue;
    stats.appendChild(el("div", { class: "workload-stat" },
      el("div", { class: "workload-stat-label", text: label }),
      el("div", { class: "workload-stat-value", text: String(value) }),
    ));
  }
  // Resources (CPU / RSS)
  const res = w.resources || {};
  if (res.cpu_percent) {
    stats.appendChild(el("div", { class: "workload-stat" },
      el("div", { class: "workload-stat-label", text: "cpu peak" }),
      el("div", { class: "workload-stat-value", text: `${res.cpu_percent.peak?.toFixed?.(0) ?? res.cpu_percent.peak}%` }),
    ));
  }
  if (res.rss_bytes) {
    stats.appendChild(el("div", { class: "workload-stat" },
      el("div", { class: "workload-stat-label", text: "rss peak" }),
      el("div", { class: "workload-stat-value", text: fmtBytes(res.rss_bytes.peak) }),
    ));
  }
  card.appendChild(stats);

  if (Array.isArray(w.samples_ns) && w.samples_ns.length > 1) {
    const wrap = el("div", { class: "workload-chart-wrap" });
    const canvas = el("canvas");
    wrap.appendChild(canvas);
    card.appendChild(wrap);

    queueMicrotask(() => {
      new Chart(canvas.getContext("2d"), {
        type: "line",
        data: {
          labels: w.samples_ns.map((_, i) => i + 1),
          datasets: [{
            label: "sample (ms)",
            data: w.samples_ns.map((ns) => ns / 1e6),
            borderColor: colorFor(idx),
            backgroundColor: colorFor(idx) + "22",
            pointRadius: 2,
            tension: 0.15,
            fill: true,
          }],
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          plugins: { legend: { display: false } },
          scales: {
            x: { title: { display: true, text: "sample" } },
            y: { title: { display: true, text: "ms" }, beginAtZero: false },
          },
        },
      });
    });
  }

  if (w.meta && Object.keys(w.meta).length) {
    const metaRow = el("div", { class: "workload-meta" });
    for (const [k, v] of Object.entries(w.meta)) {
      metaRow.appendChild(el("span", { text: `${k}=${typeof v === "object" ? JSON.stringify(v) : v}` }));
    }
    card.appendChild(metaRow);
  }

  return card;
}


if (page === "result") renderResult();
else if (page === "run") renderRun();
else if (page === "topology") { /* handled by topology.js */ }
else if (page === "index") renderIndex();
